// ========================================================
// 📰 提取和规范化RSS数据（入门版）
// ========================================================

const items = $input.all();
const results = [];
const seenUrls = new Set();

for (const item of items) {
  const data = item.json || {};

  // 提取RSS标准字段
  const title = data.title || '';
  const link = data.link || data.url || '';
  const description = data.description || data.content || '';
  const pubDate = data.pubDate || data.isoDate || new Date().toISOString();

  // 简单去重（基于URL）
  if (!link || seenUrls.has(link)) {
    continue;
  }
  seenUrls.add(link);

  // 提取来源（从link域名）
  let source = 'Unknown';
  try {
    const url = new URL(link);
    source = url.hostname.replace('www.', '');
  } catch (e) {
    source = 'RSS';
  }

  // 时间过滤（只保留最近7天）
  const pubTime = new Date(pubDate).getTime();
  const now = Date.now();
  const sevenDays = 7 * 24 * 60 * 60 * 1000;

  if (now - pubTime > sevenDays) {
    continue; // 跳过超过7天的
  }

  // 格式化日期
  let formattedDate = '';
  try {
    formattedDate = new Date(pubDate).toISOString().split('T')[0];
  } catch (e) {
    formattedDate = new Date().toISOString().split('T')[0];
  }

  results.push({
    json: {
      title: title.substring(0, 500),
      link: link,
      source: source,
      description: description.substring(0, 1000),
      pub_date: formattedDate,
      raw_content: (title + ' ' + description).toLowerCase()
    }
  });
}

console.log(`✅ 提取了 ${results.length} 条新闻`);

return results.length > 0 ? results : [{ json: { _skip: true } }];

// ========================================================
// 🔥 简单热度评分（关键词匹配）
// ========================================================

const item = $json;

if (item._skip) {
  return { json: item };
}

let score = 0;

// 高价值关键词列表
const keywords = [
  'strike', '罢工',
  'port', '港口',
  'delay', '延误',
  'disruption', '中断',
  'shipping', '航运',
  'freight', '货运',
  'container', '集装箱',
  'supply chain', '供应链',
  'logistics', '物流',
  'warehouse', '仓库',
  'customs', '海关',
  'tariff', '关税',
  'rate', '运费',
  'emergency', '紧急',
  'closure', '关闭',
  'suspension', '暂停'
];

const content = item.raw_content || '';

// 关键词匹配评分
let matchCount = 0;
for (const keyword of keywords) {
  if (content.includes(keyword)) {
    matchCount++;
  }
}

score = Math.min(matchCount * 15, 100);

// 时效性加分
const pubDate = new Date(item.pub_date);
const hoursAgo = (Date.now() - pubDate.getTime()) / (1000 * 60 * 60);

if (hoursAgo < 24) {
  score += 20;
} else if (hoursAgo < 48) {
  score += 10;
}

return {
  json: {
    新闻标题: item.title,
    来源: item.source,
    链接: item.link,
    发布日期: item.pub_date,
    热度评分: Math.min(score, 100),
    关键词: matchCount > 0 ? `匹配${matchCount}个关键词` : '无关键词',
    状态: '待处理',
    脚本: '',
    备注: ''
  }
};

// ========================================================
// 📦 构建飞书写入Body（简化版）
// ========================================================

const items = $input.all();

const records = items.map(it => {
  const j = it.json || {};
  return {
    fields: {
      "新闻标题": String(j.新闻标题 || '').substring(0, 500),
      "来源": String(j.来源 || ''),
      "链接": String(j.链接 || ''),
      "发布日期": String(j.发布日期 || ''),
      "热度评分": Number(j.热度评分) || 0,
      "状态": String(j.状态 || '待处理'),
      "关键词": String(j.关键词 || ''),
      "脚本": String(j.脚本 || ''),
      "备注": String(j.备注 || '')
    }
  };
});

console.log(`📦 准备写入 ${records.length} 条记录`);

return [{
  json: {
    body: JSON.stringify({ records: records })
  }
}];
